function skillByKey(key, customSkills) {
  const custom = (customSkills || []).find((s) => s.key === key);
  if (custom) return custom;
  return BUILTIN_SKILLS.find((s) => s.key === key);
}
var LS_ADMIN = "genki-admin-skills";
function loadAdminSkills() {
  try {
    const raw = localStorage.getItem(LS_ADMIN);
    if (!raw) return [];
    const arr = JSON.parse(raw);
    return Array.isArray(arr) ? arr : [];
  } catch {
    return [];
  }
}
function loadCustomSkills() {
  return loadAdminSkills().filter((s) => s.enabled !== false).map((s) => ({ ...s, _admin: true }));
}

