  qimen: "\u5947\u95E8\u9041\u7532\uFF1A\u4E5D\u5BAB\u516B\u95E8\u661F\u795E\uFF0C\u5B9A\u65B9\u4F4D\u4E0E\u65F6\u8FD0",
  tarot: "\u5854\u7F57\u724C\u9635\uFF1A\u724C\u9762\u610F\u8C61\u89E3\u8BFB\u5F53\u4E0B\uFF0C\u7ED9\u884C\u52A8\u6307\u5F15",
  name: "\u59D3\u540D\u5B66\uFF1A\u4E94\u884C\u914D\u7F6E\u4E0E\u6570\u7406\uFF0C\u8BBA\u65AD\u53D6\u540D\u5409\u51F6",
  fengshui: "\u98CE\u6C34\u5E03\u5C40\uFF1A\u65B9\u4F4D\u7406\u6C14\u4E0E\u5F62\u5CE6\uFF0C\u8BBA\u5C45\u5BB6\u529E\u516C\u5F00\u8FD0"
